T["Alle: Nie vor oder hinter Onyxia stehen (Atem/Schwanz).\nPhase 2 ab 65%: Feuerbaellen ausweichen, Welpen sofort umhauen.\nPhase 3 ab 40%: Furcht - Totem der Erdung und Furchtschutz bereit.\nTank: Onyxia mit dem Ruecken zur Wand, Kopf weg vom Raid.\nTank: Phase 3 sofort Aggro zurueckholen.\nHeiler: Tank hat Vorrang, in Phase 2 verteilt stehen.\nDD: Erst nach 3 Rueckenangriffen des Tanks voll loslegen.\nDD: Phase 2: Welpen vor Onyxia."] = "Todos: Nunca fique na frente ou atrás de Onyxia (sopro/cauda).\nFase 2 a partir de 65%: desvie das bolas de fogo, mate os filhotes na hora.\nFase 3 a partir de 40%: medo - Totem do Aterramento e Proteção contra Medo prontos.\nTanque: Onyxia de costas para a parede, cabeça longe da raide.\nTanque: na fase 3 recupere a ameaça na hora.\nCurador: tanque tem prioridade, fiquem espalhados na fase 2.\nDPS: só ataque com tudo após 3 Fender Armadura do tanque.\nDPS: fase 2: filhotes antes de Onyxia."
T["Alle: Schwarm-Ziel: rauslaufen.\nTank: Infernal-Tank abseits.\nHeiler: Schlaf entfernen, wo moeglich.\nDD: Infernals ignorieren, alles auf den Boss."] = "Todos: alvo do enxame: saia.\nTanque: tanque dos infernais afastado.\nCurador: remova o sono onde possível.\nDPS: ignore os infernais, tudo no chefe."
T["Alle: Tod und Verfall sofort verlassen.\nTank: Mitte halten, bei Frostnova nicht bewegen.\nHeiler: Eisblock-Ziel schnell hochheilen.\nDD: Fernkampf weit verteilt (Eispfeil-Kette)."] = "Todos: saiam de Morte e Decomposição na hora.\nTanque: segure no meio, não se mova durante a Nova Congelante.\nCurador: cure rápido o alvo do bloco de gelo.\nDPS: à distância bem espalhados (corrente de Seta de Gelo)."
