T["Den Raidplan bearbeiten duerfen Gildenleitung, Schlachtzugsleiter und Raid-Assistenten."] = "O plano de raide pode ser editado pela liderança da guilda, líderes de raide e assistentes de raide."
T["Den Talentbaum dieser Klasse kann WoW hier nicht anzeigen. Der Export-Text laesst sich unten kopieren."] = "O WoW não consegue mostrar aqui a árvore de talentos desta classe. O texto de exportação pode ser copiado abaixo."
T["Den ganzen Verlauf mit %s loeschen? Gemerkte Nachrichten gehen mit."] = "Apagar todo o histórico com %s? As mensagens salvas também serão apagadas."
T["Der Auftrag geht an alle Handwerker mit diesem Rezept - wer Zeit hat, nimmt ihn an."] = "O pedido vai para todos os artesãos com esta receita - quem tiver tempo aceita."
