T["Der Auftraggeber bekommt Bescheid, dass es fertig ist."] = "O solicitante é avisado de que está pronto."
T["Der Auftraggeber bekommt Bescheid."] = "O solicitante é avisado."
T["Der Basar ist leer"] = "O bazar está vazio"
T["Der Brachland-Chat mit seinen Spruechen"] = "O chat dos Sertões com suas frases"
T["Der Client liefert gerade keine Fertigkeiten - nach dem Einloggen kurz warten."] = "O cliente não está fornecendo habilidades agora - espere um pouco após entrar."
T["Der Dungeonkompass: welcher Dungeon passt, was droppt dort fuer dich."] = "A bússola de masmorras: qual masmorra combina, o que cai lá para você."
T["Der Gegner stand nicht vor dir. Er stand hinter dir. Die ganze Zeit."] = "O inimigo não estava na sua frente. Estava atrás de você. O tempo todo."
T["Der Gruppenanfuehrer kann dich zum Assistenten machen."] = "O líder do grupo pode tornar você assistente."
T["Der Kampf war erst gesperrt und wurde nachtraeglich ausgewertet."] = "O combate estava bloqueado e foi avaliado depois."
T["Der Knopf laesst sich nicht mehr mit der Maus verschieben"] = "O botão não pode mais ser movido com o mouse"
T["Der Link gilt fuer alle Leitungen."] = "O link vale para todas as lideranças."
T["Der Markt nutzt Preise aus dem AH-Addon Midas. Sobald du oder jemand aus der Gilde mit Midas im AH scannt, schaltet sich diese Seite frei."] = "O mercado usa preços do addon de casa de leilões Midas. Assim que você ou alguém da guilda escanear a casa de leilões com o Midas, esta página é liberada."
T["Der Mitschnitt der Spielzeiten ist aus. Schalte ihn ein, dann lernt Oasis mit jedem Abend dazu."] = "O registro dos horários de jogo está desligado. Ligue-o e o Oasis aprende a cada noite."
T["Der Oasis-Rang ist der Gilden-Rang von Oasis - er steigt durch Zusammenspielen, Helfen, Handwerk, Termine und Abzeichen."] = "O rank Oasis é o rank de guilda do Oasis - ele sobe jogando junto, ajudando, com profissões, eventos e emblemas."
T["Der Online-Sound dieser Person ist bei dir aus."] = "O som de online desta pessoa está desligado para você."
T["Der Rand des Oasis-Fensters leuchtet in deiner Farbe"] = "A borda da janela do Oasis brilha na sua cor"
T["Der Ring zeigt, wer ohne offene Punkte ist."] = "O anel mostra quem está sem pendências."
T["Der Steinfresser"] = "O Devorador de Pedras"
T["Der Termin liegt in der Vergangenheit."] = "O evento está no passado."
