T["Die Bank besucht. Mal kurz nachzaehlen."] = "Visitou o banco. Hora de recontar."
T["Die Bannliste ist leer."] = "A lista de banidos está vazia."
T["Die Chat-Eingabe war von Oasis beruehrt (z.B. 'Anfluestern'-Knopf), danach wurde /target eingegeben."] = "A entrada do chat foi tocada pelo Oasis (ex.: botão 'Sussurrar'), depois foi digitado /target."
T["Die Chat-Eingabe war von Oasis beruehrt (z.B. 'Anfluestern'-Knopf), danach wurde dort ein /cast-Befehl eingegeben."] = "A entrada do chat foi tocada pelo Oasis (ex.: botão 'Sussurrar'), depois foi digitado ali um comando /cast."
T["Die Chat-Eingabe war von Oasis beruehrt, danach wurde /focus eingegeben."] = "A entrada do chat foi tocada pelo Oasis, depois foi digitado /focus."
T["Die Chat-Eingabe war von Oasis beruehrt, danach wurde ein Zauber-Befehl eingegeben."] = "A entrada do chat foi tocada pelo Oasis, depois foi digitado um comando de feitiço."
T["Die Dungeonkarten haben keine Koordinaten. Klick hier, dann auf die Stelle der Karte, an der du gerade stehst. An zwei weit entfernten Stellen gemacht, zeigt Oasis dich und deine Gruppe auf der Karte - fuer die ganze Gilde."] = "Os mapas de masmorra não têm coordenadas. Clique aqui e depois no ponto do mapa onde você está agora. Feito em dois pontos bem distantes, o Oasis mostra você e seu grupo no mapa - para a guilda toda."
T["Die Gilde bekommt Bescheid"] = "A guilda é avisada"
T["Die Gilde sieht dabei, wem du antwortest. Standard: aus"] = "A guilda vê a quem você responde. Padrão: desligado"
T["Die Gilde sieht dein Feuer %d Minuten auf der Karte."] = "A guilda vê sua fogueira no mapa por %d minutos."
T["Die Gilde sieht in der Chronik, was du erreicht hast"] = "A guilda vê na crônica o que você alcançou"
T["Die Gilde sucht gerade nichts aus diesem Dungeon."] = "A guilda não procura nada desta masmorra no momento."
T["Die Gilde vergibt noch keine Beute-Punkte - deine Werte erscheinen, sobald die Raidleitung einen Raid startet."] = "A guilda ainda não distribui pontos de saque - seus valores aparecem assim que a liderança de raide iniciar uma raide."
T["Die Gildenbank wurde noch nicht gelesen"] = "O banco da guilda ainda não foi lido"
T["Die Gildenleitung benennt Schlachtzugsleiter und Assistenz unter Krone > Module > Raids & Beute (Namen oder ab Gildenrang). Im laufenden Raid zaehlen auch Raidleiter und Assistenten."] = "A liderança da guilda nomeia líderes e assistentes de raide em Coroa > Módulos > Raides e saque (nomes ou a partir do cargo). Em uma raide em andamento também contam o líder e os assistentes da raide."
T["Die Gildenleitung benennt Schlachtzugsleiter unter Krone > Module > Raids & Beute. Im laufenden Raid zaehlen auch Raidleiter und Assistenten."] = "A liderança da guilda nomeia líderes de raide em Coroa > Módulos > Raides e saque. Em uma raide em andamento também contam o líder e os assistentes da raide."
T["Die Gildenleitung benennt Schlachtzugsleiter unter Krone > Module > Raids & Beute. Im laufenden Raid zaehlt auch der Raidleiter."] = "A liderança da guilda nomeia líderes de raide em Coroa > Módulos > Raides e saque. Em uma raide em andamento também conta o líder da raide."
T["Die Gildenleitung erlaubt Gruppensuchen erst ab einem hoeheren Rang."] = "A liderança da guilda só permite buscas de grupo a partir de um cargo mais alto."
T["Die Gildenleitung erlaubt Umfragen erst ab einem hoeheren Rang."] = "A liderança da guilda só permite enquetes a partir de um cargo mais alto."
T["Die Gildenleitung hat die Mitstreiter-Suche abgeschaltet."] = "A liderança da guilda desativou a busca por companheiros."
T["Die Gildenleitung hat offene Einladungen abgeschaltet - fordere jemanden direkt heraus."] = "A liderança da guilda desativou convites abertos - desafie alguém diretamente."
T["Die Gildenleitung legt unter Krone > Module fest, welche Raenge das duerfen."] = "A liderança da guilda define em Coroa > Módulos quais cargos podem fazer isso."
T["Die Gildensuche von WoW hilft beim Finden - neutral, ohne Werbung."] = "A busca de guildas do WoW ajuda a encontrar - neutra, sem propaganda."
T["Die Grenze legt nur der Gildenmeister fest. Rang 1 = Gildenmeister."] = "O limite só é definido pelo Mestre da Guilda. Cargo 1 = Mestre da Guilda."
T["Die Knoepfe schreiben den Befehl in die Chatzeile - erst mit Enter wird er ausgefuehrt."] = "Os botões escrevem o comando na linha de chat - ele só é executado com Enter."
T["Die Kuerzel stehen auch in WoWs Tastaturbelegung unter AddOns > Oasis. Esc schliesst das Oasis-Fenster (im Kampf nicht - dort gehoert Esc dem Spiel)."] = "Os atalhos também estão nas Teclas de Atalho do WoW em AddOns > Oasis. Esc fecha a janela do Oasis (não em combate - lá o Esc pertence ao jogo)."
T["Die Kuerzel stehen auch in WoWs Tastaturbelegung unter AddOns > Oasis. Esc schliesst das Oasis-Fenster, solange du zuletzt hineingeklickt hast."] = "Os atalhos também estão nas Teclas de Atalho do WoW em AddOns > Oasis. Esc fecha a janela do Oasis enquanto você clicou nela por último."
T["Die Leiste rollt nach oben weg; Maus an den oberen Rand und sie kommt herunter (nur wenn sie oben angedockt ist)"] = "A barra se recolhe para cima; leve o mouse à borda superior e ela desce (só quando ancorada no topo)"
T["Die Reservierungs-Zeile erscheint nur, wenn du in einer Gruppe oder einem Schlachtzug bist"] = "A linha de reserva só aparece quando você está em um grupo ou raide"
T["Die Waechter der Sande"] = "Os Guardiões das Areias"
