T["Noch kein Ready-Check"] = "Nenhum ready check ainda"
T["Noch kein Ready-Check gelaufen."] = "Nenhum ready check feito ainda."
T["Noch kein Scan - sobald jemand mit Midas scannt, stehen hier Schnaeppchen."] = "Nenhum escaneamento ainda - quando alguém escanear com o Midas, as pechinchas aparecem aqui."
T["Noch kein Termin - melde dein Interesse, dann weiss die Raidleitung, wann es passt."] = "Nenhum evento ainda - registre seu interesse para a liderança da raide saber quando convém."
T["Noch kein Tod - weiter so!"] = "Nenhuma morte ainda - continue assim!"
T["Noch kein Tod eines seltenen Gegners erfasst."] = "Nenhuma morte de inimigo raro registrada ainda."
T["Noch keine Abklingzeiten geteilt - wer Transmutation, Mondstoff oder einen Salzstreuer hat, erscheint hier."] = "Nenhum tempo de recarga compartilhado ainda - quem tiver Transmutação, Tecido Lunar ou um Saleiro aparece aqui."
T["Noch keine Abzeichen"] = "Nenhum emblema ainda"
T["Noch keine Ausruestung bekannt - Spieler in der Naehe anvisieren und betrachten (Oasis betrachtet Mitspieler in der Gruppe automatisch)."] = "Nenhum equipamento conhecido ainda - mire e inspecione jogadores próximos (o Oasis inspeciona membros do grupo automaticamente)."
T["Noch keine Berufe gelernt."] = "Nenhuma profissão aprendida ainda."
T["Noch keine Beute aus diesem Dungeon im Gilden-Log."] = "Nenhum saque desta masmorra no registro da guilda ainda."
T["Noch keine Beute erfasst"] = "Nenhum saque registrado ainda"
T["Noch keine Bewerber. Name oben eintragen - Klick auf den Status schaltet weiter."] = "Nenhum candidato ainda. Digite um nome acima - clique no status para avançar."
T["Noch keine Daten - Ausruestung kommt mit dem naechsten Abgleich der Oasis-Nutzer."] = "Sem dados ainda - o equipamento chega na próxima sincronização dos usuários do Oasis."
T["Noch keine Daten - Mitglieder schicken ihre Messung alle 15 Min (ab dieser Version)."] = "Sem dados ainda - membros enviam sua medição a cada 15 min (a partir desta versão)."
T["Noch keine Daten - oeffne einmal das Sammlungsfenster oder trage Reittiere und Haustiere in der Tasche. Sobald Gildenmitglieder mit Oasis online sind, erscheinen sie hier."] = "Sem dados ainda - abra a janela de coleções uma vez ou carregue montarias e mascotes na bolsa. Membros da guilda com Oasis aparecem aqui quando estiverem online."
T["Noch keine Daten von der Gilde."] = "Sem dados da guilda ainda."
T["Noch keine Daten. Sobald Gildenmitglieder mit Oasis einloggen, erscheinen ihre Raid-IDs hier."] = "Sem dados ainda. Assim que membros da guilda logarem com Oasis, seus IDs de raide aparecem aqui."
T["Noch keine Dungeon-Laeufe aufgezeichnet."] = "Nenhuma incursão em masmorra registrada ainda."
T["Noch keine Dungeons geplant."] = "Nenhuma masmorra planejada ainda."
T["Noch keine Eintraege."] = "Nenhuma entrada ainda."
T["Noch keine Emojis benutzt - Favoriten aus der Emoji-Auswahl erscheinen hier."] = "Nenhum emoji usado ainda - favoritos da seleção de emojis aparecem aqui."
T["Noch keine Favoriten - Diamant anklicken."] = "Nenhum favorito ainda - clique no diamante."
T["Noch keine Favoriten - Stern oder Rechtsklick auf einen Sound."] = "Nenhum favorito ainda - estrela ou clique direito em um som."
T["Noch keine Favoriten.\nRechtsklick auf ein Emoji merkt es hier."] = "Nenhum favorito ainda.\nClique direito em um emoji para guardá-lo aqui."
T["Noch keine Fluesternachrichten."] = "Nenhum sussurro ainda."
T["Noch keine Fluesternachrichten. Schreib jemandem aus der Gilde!"] = "Nenhum sussurro ainda. Escreva para alguém da guilda!"
T["Noch keine Fraktionen entdeckt."] = "Nenhuma facção descoberta ainda."
T["Noch keine Gildenziele. Lege das erste an - z. B. eine legendaere Waffe oder Material fuer den Raid."] = "Nenhuma meta da guilda ainda. Crie a primeira - ex.: uma arma lendária ou material para a raide."
T["Noch keine Kampfberichte. Nach dem ersten Bosskampf steht hier jeder Versuch - mit Zeitstrahl der Tode und wiederkehrenden Mustern."] = "Nenhum relatório de combate ainda. Após a primeira luta de chefe, cada tentativa aparece aqui - com linha do tempo das mortes e padrões recorrentes."
T["Noch keine Kampfberichte. Nach dem ersten Bosskampf steht hier jeder Versuch."] = "Nenhum relatório de combate ainda. Após a primeira luta de chefe, cada tentativa aparece aqui."
T["Noch keine Kandidaten. Spiel mit Leuten ausserhalb der Gilde - wer ohne Gilde ist und gut bewertet wird, landet hier."] = "Nenhum candidato ainda. Jogue com pessoas fora da guilda - quem estiver sem guilda e for bem avaliado aparece aqui."
T["Noch keine Kombos.\nShift+Klick auf mehrere Emojis, dann Merken."] = "Nenhum combo ainda.\nShift+clique em vários emojis, depois Memorizar."
T["Noch keine Kontakte. Geh mit anderen Oasis-Nutzern in eine Gruppe - Oasis merkt sie sich dann hier, auch ohne Gilde."] = "Nenhum contato ainda. Agrupe-se com outros usuários do Oasis - o Oasis os memoriza aqui, mesmo sem guilda."
T["Noch keine Meilensteine. Level auf, lern Berufe - hier entsteht deine Geschichte."] = "Nenhum marco ainda. Suba de nível, aprenda profissões - sua história começa aqui."
T["Noch keine Meldungen aus der Gilde."] = "Nenhum aviso da guilda ainda."
T["Noch keine Momente - spiel einfach, Oasis schreibt mit."] = "Nenhum momento ainda - apenas jogue, o Oasis registra."
T["Noch keine Nachrichten im Offizierschat. Alles, was ab jetzt im Kanal /o geschrieben wird, steht hier."] = "Nenhuma mensagem no chat de oficiais ainda. Tudo o que for escrito no canal /o a partir de agora aparece aqui."
T["Noch keine Positionen - die Karte fuellt sich, sobald Mitglieder mit Oasis unterwegs sind."] = "Nenhuma posição ainda - o mapa se enche quando membros com Oasis estiverem por aí."
T["Noch keine Preise. Sobald jemand mit Midas im AH scannt, stehen sie hier."] = "Nenhum preço ainda. Quando alguém escanear a CL com o Midas, eles aparecem aqui."
T["Noch keine Profile gespeichert."] = "Nenhum perfil salvo ainda."
T["Noch keine Punkte"] = "Nenhum ponto ainda"
T["Noch keine Raidtage erfasst. Der Raidleiter (mit Oasis) schreibt sie bei jedem Boss-Kill automatisch mit."] = "Nenhum dia de raide registrado ainda. O líder da raide (com Oasis) os registra automaticamente a cada chefe derrotado."
T["Noch keine Regeln"] = "Nenhuma regra ainda"
T["Noch keine Regeln. Nimm eine Schnell-Vorlage oder leg oben eine eigene an."] = "Nenhuma regra ainda. Use um modelo rápido ou crie a sua acima."
T["Noch keine Rufdaten. Sie kommen automatisch, sobald Mitglieder mit Oasis online sind."] = "Sem dados de reputação ainda. Chegam automaticamente quando membros com Oasis estiverem online."
T["Noch keine Sammlung geteilt. Sobald Gildenmitglieder mit Oasis online sind, erscheinen sie hier."] = "Nenhuma coleção compartilhada ainda. Aparecem aqui quando membros da guilda com Oasis estiverem online."
T["Noch keine Sets."] = "Nenhum conjunto ainda."
T["Noch keine Sichtung. Sobald jemand mit Oasis einen seltenen Gegner sieht, steht er hier."] = "Nenhum avistamento ainda. Assim que alguém com Oasis vir um inimigo raro, ele aparece aqui."
T["Noch keine Spielzeiten bekannt. Oasis lernt mit jedem Abend, an dem du online bist - und uebernimmt die Profile der anderen."] = "Nenhum horário de jogo conhecido ainda. O Oasis aprende a cada noite em que você está online - e adota os perfis dos outros."
T["Noch keine Suche. Level eingeben und \"Suchen\" klicken - Spieler mit Gilde werden ausgeblendet."] = "Nenhuma busca ainda. Digite os níveis e clique em \"Buscar\" - jogadores com guilda são ocultados."
T["Noch keine Taktiken."] = "Nenhuma tática ainda."
T["Noch keine Taktiken. Die Raidleitung kann je Boss eine kurze Taktik anlegen - alle sehen sie hier und bekommen sie beim Anvisieren angezeigt."] = "Nenhuma tática ainda. A liderança da raide pode criar uma tática curta por chefe - todos a veem aqui e ao mirar o chefe."
T["Noch keine Talente bekannt. Mitglieder mit Oasis teilen sie automatisch; andere Spieler: anvisieren und betrachten (Rechtsklick > Betrachten) oder hier mit Ziel erneut oeffnen."] = "Nenhum talento conhecido ainda. Membros com Oasis compartilham automaticamente; outros jogadores: mire e inspecione (clique direito > Inspecionar) ou reabra aqui com o alvo."
T["Noch keine Vergaben - sie erscheinen hier, sobald die Raidleitung Beute verteilt."] = "Nenhuma atribuição ainda - aparecem aqui quando a liderança da raide distribuir saque."
T["Noch keine Werte - nach dem naechsten Kampf erscheint hier, wer vorne liegt."] = "Nenhum valor ainda - após o próximo combate, aparece aqui quem está na frente."
T["Noch keine Wunschtage - tippe an, wann du kannst."] = "Nenhum dia preferido ainda - toque quando puder."
T["Noch keine Wunschtage gemeldet."] = "Nenhum dia preferido informado ainda."
T["Noch keine Ziele. Leg oben eins an - Oasis hakt es automatisch ab."] = "Nenhuma meta ainda. Crie uma acima - o Oasis a marca automaticamente."
T["Noch keine Zusagen - sei der Erste!"] = "Nenhuma inscrição ainda - seja o primeiro!"
T["Noch keine eigene Beute"] = "Nenhum saque próprio ainda"
T["Noch keine eigene Beute erfasst (ab Qualitaet 'Selten', einstellbar)."] = "Nenhum saque seu registrado ainda (a partir da qualidade 'Raro', ajustável)."
T["Noch nicht angemeldet - waehle unten deine Rolle"] = "Ainda não inscrito - escolha sua função abaixo"
T["Noch nicht bereit"] = "Ainda não pronto"
T["Noch nicht fuer die Gilde uebernommen:"] = "Ainda não aplicado para a guilda:"
T["Noch nicht kalibriert - Kalibrieren?"] = "Ainda não calibrado - calibrar?"
T["Noch nichts auf der Wunschliste.\nTrag oben ein, was du brauchst - alle mit Oasis sehen es im Tooltip und beim Looten."] = "Nada na lista de desejos ainda.\nAdicione acima o que precisa - todos com Oasis veem no tooltip e ao saquear."
T["Noch nichts aufgezeichnet."] = "Nada registrado ainda."
T["Noch nichts benutzt."] = "Nada usado ainda."
T["Noch nichts blockiert. Sobald WoW Oasis blockiert, steht hier welche Funktion und was Oasis kurz vorher gemacht hat."] = "Nada bloqueado ainda. Assim que o WoW bloquear o Oasis, aqui aparece qual função e o que o Oasis fez logo antes."
T["Noch nichts eingelesen"] = "Nada importado ainda"
T["Noch nichts geangelt."] = "Nada pescado ainda."
T["Noch nichts gemerkt - Rechtsklick auf eine Nachricht: Nachricht merken."] = "Nada guardado ainda - clique direito em uma mensagem: Guardar mensagem."
T["Noch nichts passiert - zieht los und schreibt Geschichte!"] = "Nada aconteceu ainda - saiam e façam história!"
T["Noch nichts reserviert"] = "Nada reservado ainda"
T["Noch nichts reserviert - ein Item pro Termin."] = "Nada reservado ainda - um item por evento."
T["Noch nichts reserviert."] = "Nada reservado ainda."
T["Noch nichts verkauft."] = "Nada vendido ainda."
T["Noch nichts verteilt. Sobald eine Regel greift, steht es hier."] = "Nada distribuído ainda. Assim que uma regra se aplicar, aparece aqui."
T["Noch nie direkt mit dir abgeglichen"] = "Nunca sincronizado diretamente com você"
T["Noch niemand angefluestert."] = "Você ainda não sussurrou ninguém."
T["Noch niemand aus der Gilde hat es uebrig."] = "Ninguém da guilda tem sobrando ainda."
T["Noch niemand aus der Gilde mit deiner Spezialisierung teilt seine Talente (Oasis-Nutzer teilen automatisch)."] = "Ninguém da guilda com sua especialização compartilha talentos ainda (usuários do Oasis compartilham automaticamente)."
T["Noch niemand gegangen, seit Oasis mitschreibt."] = "Ninguém saiu desde que o Oasis começou a registrar."
T["Noch niemand gemeldet - sei der Erste!"] = "Ninguém se inscreveu ainda - seja o primeiro!"
T["Noch niemand sonst kennt das Rezept."] = "Ninguém mais conhece a receita ainda."
T["Noch niemand teilt seine Handelsbilanz."] = "Ninguém compartilha seu balanço de comércio ainda."
T["Noch niemand teilt seine Handelsbilanz. Unten 'Bilanz teilen' einschalten - dann geht's los."] = "Ninguém compartilha seu balanço de comércio ainda. Ative 'Compartilhar balanço' abaixo para começar."
T["Noch teilt niemand mit Oasis handelbare Teile. Je mehr Mitglieder Oasis nutzen, desto voller wird es hier."] = "Ninguém compartilha itens negociáveis com o Oasis ainda. Quanto mais membros usarem o Oasis, mais cheio fica aqui."
T["Noch zu uebergeben"] = "Ainda a entregar"
T["Noch zu wenig Daten fuer eine Stosszeit"] = "Dados insuficientes para um horário de pico ainda"
T["Normal"] = "Normal"
