T["Nur Banner und drei Spalten (wer ist online, was passiert, als Naechstes) - ohne Kacheln und Highlight-Zeile"] = "Só o banner e três colunas (quem está online, o que acontece, a seguir) - sem blocos nem linha de destaque"
T["Nur Dungeons, deren Beute besser ist als deine angelegte Ausruestung."] = "Só masmorras cujo saque é melhor que seu equipamento atual."
