T["Nur Mitglieder bis zu diesem Rang duerfen eine Gruppensuche starten (10 = alle)."] = "Só membros até esta patente podem iniciar uma busca de grupo (10 = todos)."
T["Nur Mitglieder bis zu diesem Rang duerfen eine neue Umfrage starten (10 = alle)."] = "Só membros até esta patente podem iniciar uma nova enquete (10 = todos)."
T["Nur Mitglieder mit Oasis. Geteilt werden offene Questitems, uebrige Questitems und teilbare Quests."] = "Só membros com Oasis. São compartilhados itens de missão pendentes, itens de missão sobrando e missões compartilháveis."
T["Nur Oasis-Spieler"] = "Só jogadores do Oasis"
T["Nur Oasis-Spieler: jeder sieht sie in seiner eigenen Sprache."] = "Só jogadores do Oasis: cada um vê no próprio idioma."
T["Nur Offiziere und Gildenleitung sehen diesen Kanal (/o)."] = "Só oficiais e liderança da guilda veem este canal (/o)."
