T["Nur Upgrades"] = "Só melhorias"
T["Nur an die eigene Gruppe, fuer die Dungeon-Karte"] = "Só para o próprio grupo, para o mapa da masmorra"
T["Nur ansehen - bearbeiten: Leitung, Schlachtzugsleiter, Raid-Assistenten"] = "Só visualizar - editar: liderança, líderes de raide, assistentes de raide"
