T["Nur der Gruppenleiter kann eine Suche starten."] = "Só o líder do grupo pode iniciar uma busca."
T["Nur der Gruppenleiter kann suchen"] = "Só o líder do grupo pode buscar"
T["Nur die Gildenleitung kann das aendern."] = "Só a liderança da guilda pode alterar isso."
T["Nur die Gildenleitung kann die Deathroll-Rangliste zuruecksetzen."] = "Só a liderança da guilda pode zerar o ranking de Deathroll."
T["Nur die wichtigsten Bereiche sind an."] = "Só as áreas mais importantes estão ligadas."
