T["Nur fuer Schlachtzugsleiter & Assistenz"] = "Só para líderes de raide e assistentes"
T["Nur fuer Umfragen, die du gestartet oder bei denen du abgestimmt hast"] = "Só para enquetes que você iniciou ou em que votou"
T["Nur fuer den Schlachtzugsleiter"] = "Só para o líder da raide"
T["Nur fuer dich sichtbar - steht im Kopf des Gespraechs mit %s."] = "Visível só para você - aparece no topo da conversa com %s."
T["Nur fuer dich: nach dem Kampf eine Zeile mit Dauer und erstem Tod"] = "Só para você: após o combate, uma linha com duração e primeira morte"
T["Nur fuer die Fehlersuche. Standard: aus"] = "Só para depuração. Padrão: desligado"
T["Nur fuer die Gildenleitung"] = "Só para a liderança da guilda"
T["Nur fuers Aussehen"] = "Só pela aparência"
T["Nur guenstig"] = "Só baratos"
T["Nur handelbare (nicht seelengebundene) Teile. Werte nach Klasse und Rolle wie beim Verbesserungs-Pfeil; Bank zaehlt erst nach einmal Oeffnen."] = "Só itens negociáveis (não vinculados à alma). Pontuados por classe e função como a seta de melhoria; o banco conta só após abri-lo uma vez."
T["Nur in der offenen Welt; kann viele Eintraege erzeugen"] = "Só no mundo aberto; pode gerar muitas entradas"
T["Nur in einer Gruppe und mit der Quest im Log."] = "Só em grupo e com a missão no registro."
T["Nur in einer Gruppe."] = "Só em grupo."
T["Nur mein Gebiet"] = "Só minha zona"
T["Nur meine"] = "Só os meus"
T["Nur mit Helfern"] = "Só com ajudantes"
T["Nur mit Upgrades"] = "Só com melhorias"
T["Nur neue"] = "Só novos"
T["Nur offene Challenges, die zu deinen Charakteren passen (Klassen, Berufe) - plus alle Dungeons, Raids, PvP und Abenteuer."] = "Só desafios abertos que combinam com seus personagens (classes, profissões) - mais todas as masmorras, raides, PvP e aventura."
T["Nur ohne Belohnungs-Auswahl und ohne Kosten. Shift = aussetzen."] = "Só sem escolha de recompensa e sem custos. Shift = pular."
T["Nur online"] = "Só online"
T["Nur von Leitern, bei denen du ueber Oasis angefragt hast"] = "Só de líderes a quem você pediu via Oasis"
T["Nur von Oasis-Nutzern"] = "Só de usuários do Oasis"
