T["Nur wenn online"] = "Só quando online"
T["OFFEN"] = "ABERTO"
T["OK"] = "OK"
T["Oasigram-Beitraege"] = "Posts do Oasigram"
T["Oasis %s ist da"] = "Oasis %s chegou"
T["Oasis %s%s ist da - du hast noch %s. Bitte im Discord herunterladen."] = "Oasis %s%s chegou - você ainda tem %s. Baixe no Discord."
T["Oasis antwortet automatisch auf pc / preis mit Item-Link im Gildenchat"] = "O Oasis responde automaticamente a pc / preço com link do item no chat da guilda"
T["Oasis begleitet %s ab heute (Stufe %d)"] = "O Oasis acompanha %s a partir de hoje (nível %d)"
T["Oasis beim Einloggen oeffnen"] = "Abrir o Oasis ao logar"
T["Oasis bekannt machen"] = "Divulgar o Oasis"
T["Oasis belegt gerade %s (Kern + geladene Module)."] = "O Oasis está usando %s (núcleo + módulos carregados)."
T["Oasis belegt gerade %s."] = "O Oasis está usando %s."
T["Oasis fasst deine Charaktere in der Gilde zu einem Spieler zusammen. Spaeter aenderbar unter Einstellungen > Profil & Sichern."] = "O Oasis agrupa seus personagens na guilda como um só jogador. Pode ser alterado depois em Configurações > Perfil e Backup."
T["Oasis funktioniert trotzdem fuer dich: dein Profil, Ziele, Dungeons und Sammlungen sind da."] = "O Oasis funciona para você mesmo assim: seu perfil, metas, masmorras e coleções estão aqui."
T["Oasis hatte Blizzard-Knoepfe (Aktionsleisten, Taschen, Tooltip, Chat) beruehrt (ab 0.5.504 behoben - bitte Oasis aktualisieren)."] = "O Oasis mexia em botões da Blizzard (barras de ação, bolsas, tooltip, chat) (corrigido a partir de 0.5.504 - atualize o Oasis)."
T["Oasis ist bereit"] = "O Oasis está pronto"
T["Oasis kann sehr viel. Waehle, was du nutzen willst - der Rest bleibt erstmal aus und laesst sich jederzeit unter 'Entdecken' einschalten."] = "O Oasis faz muita coisa. Escolha o que quer usar - o resto fica desligado por ora e pode ser ativado a qualquer momento em 'Descobrir'."
T["Oasis liest nach jedem Kampf Blizzards eingebaute Schadensanzeige - auch in Instanzen."] = "O Oasis lê o medidor de dano embutido da Blizzard após cada combate - também em instâncias."
T["Oasis liest nach jedem Kampf Blizzards eingebaute Schadensanzeige - das Kampflog ist in WoW Forever fuer Addons gesperrt. Mitspieler brauchen Oasis ab 0.5.577. Werte, die Blizzard verschluesselt (z.B. in Instanzen), zaehlen nicht."] = "O Oasis lê o medidor de dano embutido da Blizzard após cada combate - o registro de combate é bloqueado para addons no WoW Forever. Os outros jogadores precisam do Oasis 0.5.577 ou superior. Valores que a Blizzard criptografa (ex.: em instâncias) não contam."
T["Oasis oeffnen / schliessen"] = "Abrir / fechar o Oasis"
