T["Wer"] = "Quem"
T["Wer Daten schickt, die bei anderen abgelehnt werden (keine Rechte, gefaelschter Urheber, ausgedachte Eintraege). Ein unveraendertes Oasis tut das praktisch nie - ein Hinweis, kein Beweis."] = "Quem envia dados rejeitados pelos outros (sem permissão, autor falso, entradas inventadas). Um Oasis inalterado quase nunca faz isso - um indício, não prova."
T["Wer Interesse meldet, erscheint hier auf einem passenden Platz. Steht ein Termin, meldest du dich direkt auf der Karte an."] = "Quem demonstra interesse aparece aqui num horário adequado. Com evento marcado, você se inscreve direto no cartão."
T["Wer aus der Gilde das Item auf der Wunschliste hat"] = "Quem da guilda tem o item na lista de desejos"
T["Wer den Bereich in der Navigation sieht (die Gildenleitung sieht immer alles)"] = "Quem vê a área na navegação (a liderança sempre vê tudo)"
T["Wer die Gilde verlassen hat oder entfernt wurde. Kommt jemand zurueck, meldet Oasis das der Gildenleitung."] = "Quem saiu ou foi removido da guilda. Se alguém voltar, o Oasis avisa a liderança."
T["Wer die Krone oben sieht. Ohne Rechte ist sie grau und oeffnet nur eine Vorschau."] = "Quem vê a coroa no topo. Sem permissão ela fica cinza e só abre uma prévia."
T["Wer eine Nachricht oben im Gildenchat anpinnen darf"] = "Quem pode fixar uma mensagem no topo do chat da guilda"
T["Wer einladen darf, ist noch nicht bekannt - logge einmal mit deinem Main ein, dann merkt sich Oasis die Gildenleitung."] = "Ainda não se sabe quem pode convidar - entre uma vez com seu principal e o Oasis memoriza a liderança."
T["Wer geht mit nach %s? Ich suche %s"] = "Quem vai comigo para %s? Procuro %s"
T["Wer hat ...?"] = "Quem tem ...?"
T["Wer hat das Questitem, das du brauchst? Und wem kannst du helfen?"] = "Quem tem o item de missão que você precisa? E quem você pode ajudar?"
T["Wer hat was bekommen"] = "Quem recebeu o quê"
T["Wer im Raid Punkte (Einsatz/Beute) buchen darf."] = "Quem pode lançar pontos (presença/saque) na raide."
T["Wer in Gruppe oder Raid welche Buffs hat - und was noch fehlt"] = "Quem no grupo ou raide tem quais bônus - e o que ainda falta"
T["Wer ist bereit? Ampeln je Spieler"] = "Quem está pronto? Semáforo por jogador"
T["Wer ist diese Woche schon gebunden, wer ist frei und freigeschaltet - Mains und Twinks"] = "Quem já está vinculado nesta semana, quem está livre e desbloqueado - principais e alts"
T["Wer ist online"] = "Quem está online"
T["Wer ist online?"] = "Quem está online?"
T["Wer ist wann online"] = "Quem fica online quando"
T["Wer ist wie weit"] = "Quem está em que ponto"
T["Wer kann was herstellen, Markt, Gildenbank"] = "Quem fabrica o quê, mercado, banco da guilda"
T["Wer koennte mit: %s"] = "Quem poderia ir: %s"
T["Wer koennte mit?"] = "Quem poderia ir?"
T["Wer oft dabei ist und wenig bekommen hat, ist bei 'Bedarf' zuerst dran. Jede Woche verfaellt ein Teil der Punkte."] = "Quem participa muito e recebeu pouco vem primeiro em 'Necessidade'. Toda semana parte dos pontos expira."
T["Wer sich mit passender Rolle meldet, wird sofort in deine Gruppe eingeladen."] = "Quem se inscrever com função adequada é convidado na hora ao seu grupo."
T["Wer steht wo bei welcher Fraktion? Kurz vor dem Ziel, gemeinsam farmen, Fortschritt dieser Woche"] = "Quem está onde em cada facção? Quase no objetivo, farmar juntos, progresso da semana"
T["Wer teilt am meisten aus, heilt am meisten, steckt am meisten ein?"] = "Quem causa mais dano, cura mais, aguenta mais?"
T["Wer zur Gildenleitung gehoert, legt der Gildenmeister unter Krone > Gilde fest."] = "O mestre da guilda define a liderança em Coroa > Guilda."
T["Werbung"] = "Recrutamento"
T["Werte"] = "Atributos"
T["Werte bringen deiner Rolle nichts"] = "Atributos não ajudam sua função"
T["Werte nur zur Info"] = "Atributos só informativos"
T["Werte, Jahrbuch, Tagesziel, Rekorde und Abenteuer deines Charakters."] = "Atributos, anuário, meta diária, recordes e aventuras do seu personagem."
T["Werte: +Heilung, Intelligenz, Willenskraft, Mana-Reg.;Waffe: Stab oder Einhandwaffe + Nebenhand mit Heilung;Heilen: Verjuengung und Nachwachsen vorab, Heilende Beruehrung fuer grosse Treffer;Tipp: Anregen fuer Mana, Wiedergeburt fuer gefallene Heiler"] = "Atributos: +Cura, Intelecto, Espírito, reg. de mana;Arma: cajado ou uma mão + mão secundária com cura;Curar: Rejuvenescer e Recrescimento antes, Toque de Cura para dano grande;Dica: Inervar para mana, Renascimento para curadores caídos"
T["Werte: +Heilung, Intelligenz, Zauber-Krit (Erleuchtung gibt Mana zurueck), Mana-Reg.;Waffe: Einhandwaffe + Nebenhand/Schild mit Heilung;Heilen: Lichtblitz fuer kleinen Schaden, Heiliges Licht (niedriger Rang) fuer grosse Treffer;Tipp: Segen verteilen, Gottesschutz wenn du gezogen wirst"] = "Atributos: +Cura, Intelecto, crítico mágico (Iluminação devolve mana), reg. de mana;Arma: uma mão + secundária/escudo com cura;Curar: Clarão de Luz para dano pequeno, Luz Sagrada (patente baixa) para dano grande;Dica: distribuir Bênçãos, Proteção Divina se puxar aggro"
T["Werte: +Heilung, Mana-Reg. (MP5), Intelligenz - Willenskraft bringt wenig;Waffe: Einhandwaffe + Schild mit Heilung;Heilen: Kettenheilung fuer Gruppen, Welle der Heilung (niedriger Rang) fuer den Tank;Tipp: Manaquelle-Totem stellen, Erdschild auf den Tank"] = "Atributos: +Cura, reg. de mana (MP5), Intelecto - Espírito ajuda pouco;Arma: uma mão + escudo com cura;Curar: Cura em Cadeia para grupos, Onda Curativa (patente baixa) para o tanque;Dica: Totem de Fonte de Mana, Escudo Terrestre no tanque"
T["Werte: +Heilung, Willenskraft (Meditation: Regeneration auch beim Zaubern), Intelligenz, Mana-Reg.;Waffe: Stab oder Einhandwaffe + Nebenhand mit Heilung, Zauberstab;Heilen: Erneuerung und Machtwort: Schild vorab, Grosse Heilung (niedriger Rang) fuer den Tank;Tipp: Gebet der Heilung fuer die Gruppe, Verblassen bei Aggro"] = "Atributos: +Cura, Espírito (Meditação: regenera ao conjurar), Intelecto, reg. de mana;Arma: cajado ou uma mão + secundária com cura, varinha;Curar: Renovar e Palavra de Poder: Escudo antes, Cura Maior (patente baixa) para o tanque;Dica: Prece de Cura para o grupo, Desvanecer com aggro"
T["Werte: Ruestung (Baerengestalt vervielfacht sie), Ausdauer, Beweglichkeit (Ausweichen + Ruestung);Waffe: egal fuer den Schaden - nur die Werte zaehlen (Stab/Stangenwaffe mit Ausdauer);Rotation: Zermalmen, Prankenhieb fuer Gruppen, Demoralisierendes Gebruell;Tipp: Staerke fuer mehr Bedrohung, Wutanfall zum Start"] = "Atributos: Armadura (Forma de Urso multiplica), Vigor, Agilidade (esquiva + armadura);Arma: irrelevante para dano - só atributos contam (cajado/haste com Vigor);Rotação: Espancar, Golpe Giratório para grupos, Rugido Desmoralizante;Dica: Força para mais ameaça, Enfurecer no início"
T["Werte: Staerke (1 Punkt = 2 AP), Beweglichkeit (AP + Krit), Krit, Treffer bis +9 %;Waffe: egal fuer den Schaden - nur die Werte zaehlen;Rotation: Krallenhieb/Schreddern fuer Combopunkte, dann Wilder Biss;Tipp: Machtwandel (Gestalt neu) fuer Energie, aus dem Schleichen anspringen"] = "Atributos: Força (1 ponto = 2 PA), Agilidade (PA + crítico), crítico, acerto até +9 %;Arma: irrelevante para dano - só atributos contam;Rotação: Garra/Retalhar para pontos de combo, depois Mordida Feroz;Dica: trocar de forma para energia, saltar da Espreita"
T["Werte: Staerke (1 Punkt = 2 AP), Krit (loest Schlaghagel aus = schneller schlagen), Treffer bis +9 %;Waffe: langsame Zweihandwaffe - Windzorn trifft pro Schlag, also je langsamer desto mehr Schaden;Rotation: Windzorn-Waffe, Sturmschlag, Erdschock;Tipp: Totem der Staerke der Erde und Windzorn-Totem fuer die Gruppe"] = "Atributos: Força (1 ponto = 2 PA), crítico (ativa Rajada = golpes mais rápidos), acerto até +9 %;Arma: duas mãos lenta - Fúria dos Ventos acerta por golpe, quanto mais lenta mais dano;Rotação: Arma Fúria dos Ventos, Ataque Tempestuoso, Choque Terrestre;Dica: Totem de Força da Terra e Totem de Fúria dos Ventos para o grupo"
T["Werte: Staerke (1 Punkt = 2 AP), Krit, Treffer bis +9 %;Waffe: langsamer Zweihaender - Siegel und Richturteil wirken pro Schlag;Rotation: Siegel der Rechtschaffenheit/des Befehls, Richturteil, Siegel neu setzen;Tipp: Weihe nur mit genug Mana, Segen der Macht fuer dich"] = "Atributos: Força (1 ponto = 2 PA), crítico, acerto até +9 %;Arma: duas mãos lenta - Selo e Julgamento agem por golpe;Rotação: Selo da Retidão/do Comando, Julgamento, renovar selo;Dica: Consagração só com mana sobrando, Bênção do Poderio para você"
T["Werte: Treffer bis +9 %, Beweglichkeit (1 AP, ca. 29 = 1 % Krit), AP, Krit;Waffe: Kampf = schnelle Nebenhand, langsame Haupthand (Finsterer Stoss); Dolche fuer Meucheln;Rotation: Combopunkte aufbauen, Zerhaecksler oben halten, dann Ausweiden;Tipp: mit zwei Waffen verfehlen normale Schlaege oefter - Treffer ist am wichtigsten"] = "Atributos: acerto até +9 %, Agilidade (1 PA, ~29 = 1 % crítico), PA, crítico;Arma: Combate = secundária rápida, principal lenta (Golpe Sinistro); adagas para Apunhalar;Rotação: acumular pontos de combo, manter Picar e Fatiar, depois Eviscerar;Dica: com duas armas golpes normais erram mais - acerto é o mais importante"
T["Werte: Treffer bis +9 %, Beweglichkeit (2 Distanz-AP, ca. 53 = 1 % Krit), AP, Intelligenz;Waffe: langsame Distanzwaffe (hoher Schaden pro Schuss), Nahkampfwaffe mit Werten;Rotation: Mal des Jaegers, Automatischer Schuss, Zielschuss/Mehrfachschuss dazwischen;Tipp: Begleiter fuettern und gluecklich halten, Eisfalle (Quadrat) als Kontrolle"] = "Atributos: acerto até +9 %, Agilidade (2 PA à distância, ~53 = 1 % crítico), PA, Intelecto;Arma: arma à distância lenta (dano alto por tiro), arma corpo a corpo com atributos;Rotação: Marca do Caçador, Tiro Automático, Tiro Mirado/Tiro Múltiplo entre eles;Dica: alimentar o ajudante e mantê-lo feliz, Armadilha Congelante como controle"
T["Werte: Treffer bis +9 %, Staerke (1 Punkt = 2 AP), Krit (ca. 20 Beweglichkeit = 1 %);Waffe: langsamer Zweihaender (Toedlicher Stoss, Heldenhafter Stoss wirken pro Schlag);Rotation: Wut aufbauen, Toedlicher Stoss / Blutdurst, Wirbelwind, ueberschuessige Wut in Heldenhaften Stoss;Tipp: Kampfrausch-Ruf vor dem Kampf, Hinrichten unter 20 % Leben"] = "Atributos: acerto até +9 %, Força (1 ponto = 2 PA), crítico (~20 Agilidade = 1 %);Arma: duas mãos lenta (Golpe Mortal, Golpe Heroico agem por golpe);Rotação: gerar raiva, Golpe Mortal / Sede de Sangue, Redemoinho, raiva extra em Golpe Heroico;Dica: Brado de Batalha antes do combate, Executar abaixo de 20 % de vida"
T["Werte: Verteidigung (440 = auf 60 kritsicher gegen Bosse), Ausdauer, Ruestung, Schildblock;Waffe: Einhandwaffe + Schild, schnelle Waffe = mehr Wut;Rotation: Schildschlag/Rachsucht, Ruestung zerreissen auf das Ziel, Heldenhafter Stoss bei viel Wut;Tipp: Treffer hilft, damit Spott und Faehigkeiten nicht verfehlen"] = "Atributos: Defesa (440 = imune a crítico de chefes no 60), Vigor, Armadura, bloqueio;Arma: uma mão + escudo, arma rápida = mais raiva;Rotação: Escudada/Revanche, Fender Armadura no alvo, Golpe Heroico com muita raiva;Dica: acerto ajuda para Provocar e habilidades não errarem"
T["Werte: Verteidigung, Ausdauer, Ruestung, dann Zauberschaden fuer mehr Bedrohung;Waffe: Einhandwaffe (gern mit Zauberschaden) + Schild;Rotation: Zorn der Gerechtigkeit an, Weihe fuer Gruppen, Heiliger Schild oben halten;Tipp: Mana ist knapp - Siegel der Weisheit oder Intelligenz mitnehmen"] = "Atributos: Defesa, Vigor, Armadura, depois dano mágico para mais ameaça;Arma: uma mão (de preferência com dano mágico) + escudo;Rotação: ligar Fúria Justa, Consagração para grupos, manter Escudo Sagrado;Dica: mana é pouca - leve Selo da Sabedoria ou Intelecto"
T["Werte: Zauberschaden, Zauber-Krit (Elementarfokus spart Mana), Intelligenz, Mana-Reg.;Waffe: Einhandwaffe + Schild/Nebenhand mit Zauberschaden;Rotation: Blitzschlag spammen, Kettenblitz bei Gruppen, Flammenschock;Tipp: Zaubertreffer bis +16 % im Raid, Manaquelle-Totem gegen leeres Mana"] = "Atributos: dano mágico, crítico mágico (Foco Elemental poupa mana), Intelecto, reg. de mana;Arma: uma mão + escudo/secundária com dano mágico;Rotação: spam de Raio, Cadeia de Raios em grupos, Choque Flamejante;Dica: acerto mágico até +16 % na raide, Totem de Fonte de Mana contra mana vazia"
T["Werte: Zauberschaden, Zauber-Krit, Intelligenz, Zaubertreffer bis +16 % im Raid;Waffe: Stab oder Einhandwaffe + Nebenhand mit Zauberschaden;Rotation: Mondfeuer + Insektenschwarm, dann Zorn oder Sternenfeuer;Tipp: Anregen fuer dich selbst, wenn das Mana knapp wird"] = "Atributos: dano mágico, crítico mágico, Intelecto, acerto mágico até +16 % na raide;Arma: cajado ou uma mão + secundária com dano mágico;Rotação: Fogo Lunar + Enxame de Insetos, depois Ira ou Fogo Estelar;Dica: Inervar em si mesmo quando a mana acabar"
T["Werte: Zauberschaden, Zaubertreffer bis +16 % (Raid), Ausdauer, Intelligenz;Waffe: Stab oder Dolch + Nebenhand mit Zauberschaden, Zauberstab fuer Restmana;Rotation: Verderbnis + Fluch, dann Schattenblitz; Aderlass statt Trinken;Tipp: Ausdauer lohnt sich doppelt (Aderlass, Leerwandler/Seelenverbindung)"] = "Atributos: dano mágico, acerto mágico até +16 % (raide), Vigor, Intelecto;Arma: cajado ou adaga + secundária com dano mágico, varinha para mana restante;Rotação: Corrupção + maldição, depois Seta Sombria; Drenar Vida em vez de beber;Dica: Vigor vale em dobro (Drenar Vida, Emissário do Caos/Elo Anímico)"
T["Werte: Zauberschaden, Zaubertreffer bis +16 % (Raid), Willenskraft fuer Mana;Waffe: Stab oder Einhandwaffe + Nebenhand mit Zauberschaden;Rotation: Schattenwort: Schmerz, Gedankenschlag, Gedankenschinden;Tipp: Schattengestalt dauerhaft an, Vampirumarmung heilt die Gruppe"] = "Atributos: dano mágico, acerto mágico até +16 % (raide), Espírito para mana;Arma: cajado ou uma mão + secundária com dano mágico;Rotação: Palavra Sombria: Dor, Explosão Mental, Tortura Mental;Dica: Forma de Sombra sempre ligada, Abraço Vampírico cura o grupo"
T["Werte: Zauberschaden, dann Zaubertreffer bis +16 % (Raid-Bosse), Intelligenz, Zauber-Krit;Waffe: Stab mit Zauberschaden, dazu ein Zauberstab fuer Restmana;Rotation: Frostblitz bzw. Feuerball spammen, Hervorrufung bei leerem Mana;Leveln: Intelligenz und Willenskraft = weniger Pausen, in Gruppen Schaf (Mond) setzen"] = "Atributos: dano mágico, depois acerto mágico até +16 % (chefes de raide), Intelecto, crítico mágico;Arma: cajado com dano mágico, mais uma varinha para mana restante;Rotação: spam de Seta de Gelo ou Bola de Fogo, Evocação com mana vazia;Upar: Intelecto e Espírito = menos pausas, em grupo use Metamorfose (Lua)"
