T["Zeigt BESSER / SCHLECHTER / NICHT TRAGBAR mit Auswirkung (DPS, Leben, Ruestung) und Werte-Tabelle. Blizzards Vergleich erscheint dann nur mit Shift. Ist nesUI mit eigenem Vergleich geladen, zeigt Oasis nichts (sonst doppelt) - dort mit /nes vergleich abschalten."] = "Mostra MELHOR / PIOR / NÃO EQUIPÁVEL com impacto (DPS, vida, armadura) e tabela de atributos. A comparação da Blizzard só aparece com Shift. Se o nesUI estiver carregado com comparação própria, o Oasis não mostra nada (senão duplica) - desative lá com /nes vergleich."
T["Zeigt Besser / Schlechter / Nicht tragbar mit Auswirkung (DPS, Leben, Ruestung) und Werte-Tabelle. Blizzards Vergleich erscheint dann nur mit Shift. Ist nesUI mit eigenem Vergleich geladen, zeigt Oasis nichts (sonst doppelt) - dort mit /nes vergleich abschalten."] = "Mostra Melhor / Pior / Não equipável com impacto (DPS, vida, armadura) e tabela de atributos. A comparação da Blizzard só aparece com Shift. Se o nesUI estiver carregado com comparação própria, o Oasis não mostra nada (senão duplica) - desative lá com /nes vergleich."
