T["1.  Kampflog mitschreiben lassen (Einstellungen > Bereiche > Kampf-Rangliste, steht auf an).\n2.  Nach dem Spielen im Oasis-Ordner ImportCrits.bat doppelklicken.\n3.  Im Spiel /reload - dein hoechster Crit steht hier und wird mit der Gilde geteilt."] = "1.  Deixe o registro de combate ligado (Configurações > Áreas > Classificação de combate, ligado por padrão).\n2.  Depois de jogar, dê dois cliques em ImportCrits.bat na pasta do Oasis.\n3.  /reload no jogo - seu maior crítico aparece aqui e é compartilhado com a guilda."
T["1. Ueberschrift"] = "1. Título"
T["2 Min"] = "2 min"
T["2. Nachricht"] = "2. Mensagem"
T["3D-Modell"] = "Modelo 3D"
T["5 Min"] = "5 min"
T["Abend-Check"] = "Checagem da noite de raide"
T["Aktionen"] = "Ações"
T["Aktiv: Meme-Sounds, Musik und Gilden-Emojis sind enthalten."] = "Ativo: sons de meme, música e emojis da guilda incluídos."
T["Aktive Mitglieder unterhalb der Offiziersraenge erscheinen nach so vielen Tagen im selben Rang in der Liste 'Befoerderung'. 0 = aus."] = "Membros ativos abaixo dos ranks de oficial aparecem na lista 'Promoção' após tantos dias no mesmo rank. 0 = desligado."
T["Aktuelles Gebiet zuerst"] = "Zona atual primeiro"
T["Alle Bereiche, nach Themen gruppiert: Gilde, Zusammen spielen, Raid, Handel, Spass. Ein Klick auf eine Ueberschrift klappt die Gruppe zu."] = "Todas as áreas, agrupadas por tema: guilda, jogar juntos, raide, comércio, diversão. Clique num título para recolher o grupo."
T["Alle Gebiete aufklappen"] = "Expandir todas as zonas"
T["Alle Gebiete zuklappen"] = "Recolher todas as zonas"
T["Alle Mitglieder mit Rang, Stufe und Oasis-Version. Rechtsklick auf eine Zeile: Rang aendern."] = "Todos os membros com rank, nível e versão do Oasis. Clique direito numa linha: mudar rank."
T["Alle Schriften unter der SIL Open Font License 1.1"] = "Todas as fontes sob a SIL Open Font License 1.1"
T["Alle: Brennendes Adrenalin: SOFORT aus dem Raid laufen (du stirbst gleich).\nAlle: Volle Ressourcen am Anfang - alles raushauen.\nTank: Tank-Reihenfolge festlegen (Adrenalin auf dem Tank).\nDD: Nicht vor oder hinter den Drachen."] = "All: Adrenalina Ardente: corra para fora da raide NA HORA (você vai morrer).\nAll: Recursos cheios no início - use tudo.\nTank: Definir ordem dos tanks (Adrenalina no tank).\nDD: Não fique na frente nem atrás do dragão."
T["Alle: Die 8 Feuerwichtel nicht in der Naehe des Raids sterben lassen (Explosion).\nTank: Jeder Wichtel-Tank zieht seinen Wichtel weg, Hexer verbannen.\nHeiler: Bannen, Wichtel-Tanks im Blick.\nDD: Garr zuerst, Wichtel nur gezielt."] = "All: Não deixem os 8 Firesworn morrerem perto da raide (explosão).\nTank: Cada tank de add puxa seu Firesworn para longe, bruxos banem.\nHealer: Dissipar, de olho nos tanks de add.\nDD: Garr primeiro, adds só quando chamado."
T["Alle: Die beiden Kernhunde weg vom Boss tanken, nicht toeten.\nTank: Golemagg-Tank wechseln, wenn Magmasplitter zu hoch stapeln.\nDD: Nur auf Golemagg."] = "All: Tankar os dois Core Ragers longe do chefe, não matar.\nTank: Trocar o tank do Golemagg quando Magma Splash acumular demais.\nDD: Só no Golemagg."
T["Alle: Erst die 4 Priester, sie heilen sich gegenseitig.\nTank: Herold und Priester getrennt.\nDD: Unterbrechen! Dunkle Besserung der Priester stoppen."] = "All: Primeiro os 4 sacerdotes, eles se curam entre si.\nTank: Manter Sulfuron e os sacerdotes separados.\nDD: Interromper! Parar o Dark Mending dos sacerdotes."
T["Alle: Feuerschutz! Wrath of Ragnaros wirft den Nahkampf weg - danach wieder ran.\nAlle: Phase der Soehne (nach 3 Min oder bei Untertauchen): alle Soehne der Flamme toeten.\nTank: Zweiter Tank bereit, wenn der erste weggeworfen wird.\nHeiler: Verteilt, Fernkampf nicht zu nah (Lavaplatscher).\nDD: Nahkampf: Mana unter Kontrolle, Fernkampf auf Abstand."] = "All: Proteção contra fogo! Ira de Ragnaros arremessa o corpo a corpo - depois voltem.\nAll: Fase dos Filhos (após 3 min ou quando ele submerge): matar todos os Filhos da Chama.\nTank: Segundo tank pronto quando o primeiro for arremessado.\nHealer: Espalhados, distância não muito perto (Estouro de Lava).\nDD: Corpo a corpo: mana sob controle, distância mantém afastado."
T["Alle: Flammenpuffer stapelt - Fernkampf hinter Saeulen zum Abbauen.\nTank: Zwei Tanks hinter Saeulen, Flugelschlag wirft zurueck.\nDD: Onyxiaschuppenumhang Pflicht."] = "All: Flame Buffet acumula - distância atrás dos pilares para deixar cair.\nTank: Dois tanks atrás dos pilares, Wing Buffet empurra.\nDD: Manto de Escamas de Onyxia obrigatório."
T["Alle: Fluch des Gehennas (weniger Heilung) sofort entfernen.\nAlle: Aus dem Feuerregen raus.\nTank: Die zwei Flammenwichtel getrennt tanken.\nDD: Wichtel zuerst, dann Gehennas."] = "All: Remover a Maldição de Gehennas (menos cura) na hora.\nAll: Sair da Chuva de Fogo.\nTank: Tankar os dois Flamewakers separados.\nDD: Flamewakers primeiro, depois Gehennas."
T["Alle: Fluch des Lucifron und Drohende Verdammnis sofort entfernen (Magier/Druiden, Priester/Paladine).\nTank: Die beiden Wachen getrennt tanken - Gedankenkontrolle!\nHeiler: Verteilt stehen, gedankenkontrollierte Spieler bannen.\nDD: Erst die Wachen, dann Lucifron."] = "All: Remover Maldição de Lucifron e Impending Doom na hora (magos/druidas, sacerdotes/paladinos).\nTank: Tankar os dois guardas separados - controle mental!\nHealer: Fiquem espalhados, dissipar jogadores controlados.\nDD: Primeiro os guardas, depois Lucifron."
T["Alle: Lebende Bombe: SOFORT raus aus dem Raid laufen!\nAlle: Inferno - weg vom Boss, Mana-Ausloeschung bannen.\nTank: Mitte halten, bei Inferno kurz raus.\nDD: Nahkampf bei Inferno zurueck."] = "All: Bomba Viva: corra para fora da raide NA HORA!\nAll: Inferno - longe do chefe, dissipar Ignite Mana.\nTank: Segurar o meio, sair um pouco no Inferno.\nDD: Corpo a corpo recua no Inferno."
T["Alle: Magiereflexion/Schadensschild der Wachen beachten - dann Schaden stoppen.\nTank: Jeder Tank eine Wache, Magier schafen die Elitewachen.\nDD: Heiler-Wachen (Flamewaker Healer) zuerst."] = "All: Atenção ao reflexo de magia/escudo de dano dos guardas - aí parem o dano.\nTank: Um guarda por tank, magos transformam os guardas de elite.\nDD: Guardas curandeiros (Flamewaker Healer) primeiro."
T["Alle: Nie vor oder hinter Onyxia stehen (Atem und Schwanzfeger).\nAlle: Phase 2 (65%): Feuerbaellen ausweichen, nicht in die Hoehlen-Eingaenge.\nAlle: Phase 3 (40%): Furcht - Furchtschutz/Erdungstotem bereit, Lava-Risse meiden.\nTank: Onyxia seitlich an der Wand, Kopf weg vom Raid.\nTank: Phase 2: Welpen einsammeln. Phase 3: Aggro sofort zurueck.\nHeiler: Tank hat Vorrang, in Phase 2 verteilt stehen.\nDD: 3 Angriffe des Tanks abwarten. Phase 2: Welpen zuerst."] = "All: Nunca fique na frente nem atrás da Onyxia (sopro e rabada).\nAll: Fase 2 (65%): desviar das bolas de fogo, fora das entradas das cavernas.\nAll: Fase 3 (40%): medo - Proteção contra Medo/Totem Sísmico prontos, evitar as fendas de lava.\nTank: Onyxia de lado na parede, cabeça longe da raide.\nTank: Fase 2: pegar os filhotes. Fase 3: recuperar a aggro na hora.\nHealer: Tank tem prioridade, espalhados na fase 2.\nDD: Esperar 3 ataques do tank. Fase 2: filhotes primeiro."
T["Alle: Panik - Furchtschutz/Erdungstotem, Jaeger: Einlullender Schuss bei Raserei.\nAlle: Aus dem Lavafeuer am Boden raus.\nTank: Magmadar mit dem Ruecken zum Raid.\nDD: Fernkampf hinten verteilt."] = "All: Pânico - Proteção contra Medo/Totem Sísmico, caçadores: Tiro Tranquilizante no Frenesi.\nAll: Sair do fogo de lava no chão.\nTank: Magmadar de costas para a raide.\nDD: Distância espalhada atrás."
T["Alle: Phase 1: Drachkin aus beiden Seiten, Klassenrufe beachten.\nAlle: Phase 3 (20%): Skelette wieder auferstanden - erneut toeten.\nTank: Nefarian an der Wand, Furcht - Furchtschutz.\nHeiler: Klassenruf fuer Priester: Heilung schadet - aufpassen.\nDD: Jaeger/Krieger: Klassenrufe beachten (Waffen weg, Haltung)."] = "All: Fase 1: dracônicos dos dois lados, atenção aos chamados de classe.\nAll: Fase 3 (20%): os esqueletos se levantam - matar de novo.\nTank: Nefarian na parede, medo - Proteção contra Medo.\nHealer: Chamado de classe dos sacerdotes: cura causa dano - cuidado.\nDD: Caçadores/guerreiros: atenção aos chamados de classe (sem armas, postura)."
T["Alle: Phase 1: Eier zerstoeren (Gedankenkontrolle der Kugel), Adds abfangen.\nAlle: Nach allen Eiern: Boss im Raum - Feuerball-Nova.\nTank: Adds an den Treppen sammeln.\nDD: Magier und Drachkin zuerst."] = "All: Fase 1: destruir os ovos (controle mental pelo orbe), pegar os adds.\nAll: Depois de todos os ovos: chefe na sala - Nova de Fogo.\nTank: Juntar os adds nas escadas.\nDD: Magos e dracônicos primeiro."
T["Alle: Raserei - Jaeger: Einlullender Schuss.\nTank: Zwei Tanks, Flugelschlag beachten.\nDD: Onyxiaschuppenumhang Pflicht."] = "All: Frenesi - caçadores: Tiro Tranquilizante.\nTank: Dois tanks, atenção ao Wing Buffet.\nDD: Manto de Escamas de Onyxia obrigatório."
T["Alle: Schatten der Schattenschwinge heilt den Boss - Tank mit Debuff tauscht.\nTank: Zwei Tanks wechseln bei Schatten.\nDD: Onyxiaschuppenumhang Pflicht."] = "All: Shadow of Ebonroc cura o chefe - o tank com o debuff troca.\nTank: Dois tanks trocam na Sombra.\nDD: Manto de Escamas de Onyxia obrigatório."
T["Alle: Stoss zurueck - an die Wand stellen.\nTank: Zwei Tanks, Aggro wird durch Niederschlagen geteilt.\nDD: Mortalschlag auf Tank: Heiler vorbereiten."] = "All: Empurrão - fiquem contra a parede.\nTank: Dois tanks, a aggro é dividida pelo Knock Away.\nDD: Golpe Mortal no tank: curandeiros preparados."
T["Alle: Teleportiert sich - wer Aggro hat, nicht wegrennen.\nAlle: Fluch des Shazzrah entfernen, Arkane Explosion: Nahkampf auf Abstand.\nTank: Nach jedem Blinzeln sofort wieder ran.\nHeiler: Bannen (Deaktivieren-Magie)."] = "All: Ele se teleporta - quem tiver aggro, não corra.\nAll: Remover a Maldição de Shazzrah, Explosão Arcana: corpo a corpo mantém distância.\nTank: Voltar nele logo após cada lampejo.\nHealer: Dissipar (Deaden Magic)."
T["Alle: Zwei der fuenf Atem-Arten je Woche - Atem verlaesst man hinter der Ecke.\nAlle: Hourglass Sand fuer Bronze-Affliktion.\nTank: Am Tor tanken, Raid hinter der Ecke.\nDD: Bei Raserei Einlullender Schuss."] = "All: Dois dos cinco tipos de sopro por semana - evite o sopro atrás da quina.\nAll: Areia da Ampulheta para a aflição Bronze.\nTank: Tankar no portão, raide atrás da quina.\nDD: Tiro Tranquilizante no Frenesi."
T["Alt halten: alle Werte und Bewertung. Shift: Blizzard-Vergleich."] = "Segure Alt: todos os atributos e detalhes da nota. Shift: comparação da Blizzard."
T["Alt loslassen: kompakter Vergleich. Shift: Blizzard-Vergleich."] = "Solte Alt: visão compacta. Shift: comparação da Blizzard."
