T["Charakterstatistik - hoechster Einzelwert, Crit-Status unbekannt"] = "Estatística do personagem – maior valor único, crítico ou não: desconhecido"
T["Chat-Eingabe und Zauberbefehle koennen beteiligt sein."] = "Entrada do chat e comandos de feitiço podem estar envolvidos."
T["Chat-Eingabe und Zielwechsel koennen beteiligt sein."] = "Entrada do chat e trocas de alvo podem estar envolvidas."
T["Chatnachrichten erfordern in diesem Client eine direkte Eingabe."] = "Mensagens de chat exigem entrada direta neste cliente."
T["Credits"] = "Créditos"
T["Crit-Heilung"] = "Cura crítica"
T["Crit-Import gehoert zu einem anderen Charakter."] = "A importação de críticos pertence a outro personagem."
T["Crit-Quelle pruefen"] = "Verificar fonte do crítico"
T["Crit-Rekorde aus den Kampflog-Dateien uebernommen."] = "Recordes de crítico importados dos arquivos de registro de combate."
T["Crits beim Kampf allein automatisch zaehlen"] = "Contar críticos automaticamente ao lutar sozinho"
T["Crits in Gruppe und Dungeon schaetzen"] = "Estimar críticos em grupo e masmorra"
T["Das X am Fenster klappt Oasis in die Leiste ein. Das X an der Leiste schliesst ganz."] = "O X da janela recolhe o Oasis na barra. O X da barra fecha de vez."
T["Das gelbe Ausrufezeichen am Symbol zeigt das an."] = "O ponto de exclamação amarelo no ícone indica isso."
T["Das war nur Glueck! Nochmal!"] = "Foi pura sorte! De novo!"
T["Das war's schon. Den Rundgang findest du jederzeit wieder unter Einstellungen > Status oder mit /oa rundgang."] = "É só isso. O tour está sempre em Configurações > Status ou com /oa rundgang."
T["Daten"] = "Dados"
T["Deckend"] = "Opaco"
T["Dein Charakter"] = "Seu personagem"
T["Deine Stats: Oasis-Rang, Abzeichen und alle Zaehler"] = "Suas estatísticas: rank Oasis, emblemas e todos os contadores"
T["Den Download findest du im Discord der Gilde."] = "O download está no Discord da guilda."
T["Der Client erlaubt Oasis nicht, das Kampflog einzuschalten - bitte selbst /combatlog eingeben."] = "O cliente não deixa o Oasis ligar o registro de combate - digite /combatlog você mesmo."
T["Der Inhalt des gewaehlten Bereichs. Die Uebersicht zeigt, wer online ist, was ansteht und was es Neues gibt."] = "O conteúdo da área escolhida. A visão geral mostra quem está online, o que vem aí e o que há de novo."
T["Der Minimap-Knopf oder /oa oeffnet Oasis. Mit dem Strich oben rechts wird das Fenster zu einer schmalen Leiste."] = "O botão do minimapa ou /oa abre o Oasis. O traço no canto superior direito transforma a janela numa barra fina."
T["Der Offizierskanal (/o) mit Verlauf - nur fuer Raenge mit Offizierschat-Recht."] = "O canal de oficiais (/o) com histórico - só para ranks com permissão de chat de oficial."
T["Der gelbe Strich links in der Liste zeigt das an."] = "A barra amarela à esquerda na lista indica isso."
T["Details schliessen"] = "Fechar detalhes"
T["Deutlicher Standard-Ton bei Online-Meldungen"] = "Som padrão nítido nos avisos de online"
T["Die Charakterstatistik ist in diesem Client nicht verfuegbar."] = "As estatísticas do personagem não estão disponíveis neste cliente."
T["Die Gildenleitung hat Soundeffekte fuer dich gesperrt."] = "A liderança da guilda silenciou efeitos sonoros para você."
T["Die Leiste ist ab dem Einloggen da und bleibt - das X am Fenster schliesst nur das Fenster."] = "A barra aparece desde o login e fica - o X da janela só fecha a janela."
T["Die Prozentzahl vergleicht die Item-Wertung fuer deine Rolle, nicht deinen gesamten Schaden. Auswirkungen sind Schaetzwerte."] = "A porcentagem compara a nota do item para sua função, não seu dano total. Os efeitos são estimativas."
T["Die Statistik liefert derzeit keinen lesbaren Wert."] = "A estatística não fornece um valor legível no momento."
T["Die Zentrale eurer Gilde. In 30 Sekunden kennst du dich aus - hier ist das Wichtigste."] = "A central da sua guilda. Em 30 segundos você se orienta - aqui está o principal."
T["Die geschuetzte Funktion wurde blockiert. Der genaue Ausloeser ist noch unbekannt."] = "A função protegida foi bloqueada. A causa exata ainda é desconhecida."
T["Die passende Charakterstatistik wurde noch nicht gefunden."] = "A estatística de personagem correspondente ainda não foi encontrada."
T["Die vollstaendigen Lizenztexte liegen im Oasis-Ordner: CREDITS.txt, LICENSE und LICENSE-MIT.txt."] = "Os textos completos das licenças estão na pasta do Oasis: CREDITS.txt, LICENSE e LICENSE-MIT.txt."
T["Diese Gildenraenge (0 = Gildenmeister) duerfen im Beuterat abstimmen."] = "Estes ranks da guilda (0 = Mestre da Guilda) podem votar no conselho de saque."
