T["Wer an einem Abend schon ein Item mit Bedarf bekommen hat, rutscht bei Bedarf hinter alle ohne Item (gleicher Wurf-Rang)."] = "Quem já recebeu um item por necessidade na noite fica atrás de todos sem item na necessidade (mesmo nível de rolagem)."
T["Wer ein Item fuer den Termin reserviert hat, kommt bei Bedarf vor allen anderen."] = "Quem reservou um item para o evento vem antes de todos na necessidade."
T["Wer in Gruppe oder Raid welche Buffs hat - und wer das Fehlende geben kann"] = "Quem tem quais buffs no grupo ou raide - e quem pode dar o que falta"
