T["Wie die Schrift"] = "Igual ao texto"
T["Wieder am Talentfenster andocken"] = "Prender de novo à janela de talentos"
T["WoW sagt Addons in der Gruppe nicht, wer getroffen hat. Oasis zaehlt einen kritischen Treffer nur, wenn er direkt auf deinen eigenen Angriff folgt und nach dem Kampf zur Schadensanzeige passt. In der Rangliste als geschaetzt markiert."] = "Em grupo o WoW não informa aos addons quem acertou. O Oasis só conta um crítico se ele vem logo após seu ataque e bate com o medidor de dano após a luta. Marcado como estimado na classificação."
T["WoW-Klassiker"] = "Clássicos do WoW"
T["Wochenaufgaben %d/%d"] = "Tarefas semanais %d/%d"
T["World of Warcraft und zugehoerige Namen, Wappen und Grafiken sind Marken von Blizzard Entertainment. Oasis ist ein Fan-Projekt und steht in keiner Verbindung zu Blizzard."] = "World of Warcraft e nomes, brasões e artes relacionados são marcas da Blizzard Entertainment. O Oasis é um projeto de fãs e não tem vínculo com a Blizzard."
T["Wuerfeln: Reihenfolge Bedarf > Zweitspec > Transmog, dann Wurf. Punkte: Prioritaet aus den Beutepunkten entscheidet. Beuterat: Offiziere stimmen ab, der Plundermeister vergibt."] = "Rolagem: ordem necessidade > spec secundária > transmog, depois a rolagem. Pontos: a prioridade dos pontos de saque decide. Conselho de saque: oficiais votam, o mestre do saque entrega."
T["Zahnrad = Einstellungen (Aussehen, Toene, Hinweise). Daneben Sprache und - fuer die Gildenleitung - die Krone."] = "Engrenagem = configurações (aparência, sons, notificações). Ao lado, o idioma e - para a liderança da guilda - a coroa."
